<?php namespace LaraSelector\Tests; use LaraSelector\LaraSelectorToken; class SourceTokenTest extends TestCase { public function test_rejects_tampered_identifiers(): void { $t=app(LaraSelectorToken::class); $this->expectException(\InvalidArgumentException::class); $t->resolve('../../etc/passwd.bad'); } public function test_token_round_trip(): void { $file=__DIR__.'/fixtures/sample.blade.php'; $t=app(LaraSelectorToken::class); $s=$t->resolve($t->make($file, 3)); $this->assertSame('tests/fixtures/sample.blade.php',$s['relative']);$this->assertSame(3,$s['line']); } }
